import{_ as t,o as i,c as a,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"Template Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/01-template-bill-import-guide.md","filePath":"v1/en/guide/01-template-bill-import-guide.md"}'),l={name:"v1/en/guide/01-template-bill-import-guide.md"};function o(s,e,d,n,p,h){return i(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="template-bill-import-guide" tabindex="-1">Template Bill Import Guide <a class="header-anchor" href="#template-bill-import-guide" aria-label="Permalink to &quot;Template Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>Koala supports importing bills from external files, which is useful when you migrate historical records. Supported import sources:</p><ul><li><strong>Template file import</strong>: import a standard CSV file</li><li><strong>WeChat bill import</strong>: import a bill file exported from WeChat</li><li><strong>Alipay bill import</strong>: import a bill file exported from Alipay</li><li><strong>Pixiu bill import</strong>: import a CSV file exported from Pixiu</li><li><strong>iCost bill import</strong>: import an Excel file exported from iCost</li></ul><hr><h2 id="📁-supported-file-formats" tabindex="-1">📁 Supported File Formats <a class="header-anchor" href="#📁-supported-file-formats" aria-label="Permalink to &quot;📁 Supported File Formats&quot;">​</a></h2><ul><li><strong>CSV</strong> (<code>.csv</code>): Alipay, Pixiu, Template</li><li><strong>Excel</strong> (<code>.xlsx</code>, <code>.xls</code>): WeChat, iCost</li></ul><hr><h2 id="🚀-quick-start" tabindex="-1">🚀 Quick Start <a class="header-anchor" href="#🚀-quick-start" aria-label="Permalink to &quot;🚀 Quick Start&quot;">​</a></h2><h3 id="step-1-open-the-import-page" tabindex="-1">Step 1: Open the import page <a class="header-anchor" href="#step-1-open-the-import-page" aria-label="Permalink to &quot;Step 1: Open the import page&quot;">​</a></h3><ol><li>Open Koala</li><li>Tap <strong>Settings</strong></li><li>Find <strong>Bill Import</strong></li><li>Enter the bill import page</li></ol><h3 id="step-2-choose-the-import-source" tabindex="-1">Step 2: Choose the import source <a class="header-anchor" href="#step-2-choose-the-import-source" aria-label="Permalink to &quot;Step 2: Choose the import source&quot;">​</a></h3><ul><li><strong>Template file</strong>: standard-format CSV</li><li><strong>WeChat</strong>: WeChat-exported bill file</li><li><strong>Alipay</strong>: Alipay-exported bill file</li><li><strong>Pixiu</strong>: Pixiu-exported bill file</li><li><strong>iCost</strong>: iCost-exported bill file</li></ul><blockquote><p>⚠️ <strong>Important</strong>: Choose the correct source, otherwise parsing may fail.</p></blockquote><h3 id="step-3-pick-a-file" tabindex="-1">Step 3: Pick a file <a class="header-anchor" href="#step-3-pick-a-file" aria-label="Permalink to &quot;Step 3: Pick a file&quot;">​</a></h3><ol><li>Tap <strong>File path</strong></li><li>Select the file in the file picker</li><li>Confirm the file name is shown</li></ol><h3 id="step-4-link-a-ledger" tabindex="-1">Step 4: Link a ledger <a class="header-anchor" href="#step-4-link-a-ledger" aria-label="Permalink to &quot;Step 4: Link a ledger&quot;">​</a></h3><ol><li>Tap <strong>Linked ledger</strong></li><li>Choose the ledger you want to import into</li></ol><h3 id="step-5-parse-preview-and-import" tabindex="-1">Step 5: Parse, preview, and import <a class="header-anchor" href="#step-5-parse-preview-and-import" aria-label="Permalink to &quot;Step 5: Parse, preview, and import&quot;">​</a></h3><ol><li>Tap <strong>Parse</strong> (top-right)</li><li>Review records on the preview page</li><li>Edit or delete invalid records if needed</li><li>Tap <strong>Import</strong></li></ol><hr><h2 id="📝-template-csv-format" tabindex="-1">📝 Template CSV Format <a class="header-anchor" href="#📝-template-csv-format" aria-label="Permalink to &quot;📝 Template CSV Format&quot;">​</a></h2><p>To import via template file, prepare a CSV in the format below.</p><h3 id="csv-requirements" tabindex="-1">CSV requirements <a class="header-anchor" href="#csv-requirements" aria-label="Permalink to &quot;CSV requirements&quot;">​</a></h3><ol><li><strong>Encoding</strong>: UTF-8 or GBK</li><li><strong>Delimiter</strong>: comma <code>,</code></li><li><strong>Header row</strong>: required in the first line</li></ol><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">类型,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">金额,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">分类,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">账户,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">备注,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">标签</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">支出,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">100.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">餐饮,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">现金,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">午餐,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">工作餐</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-02,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">收入,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">5000.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">工资,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">银行卡,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">月薪,</span></span></code></pre></div><h3 id="field-reference" tabindex="-1">Field reference <a class="header-anchor" href="#field-reference" aria-label="Permalink to &quot;Field reference&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Required</th><th>Example</th></tr></thead><tbody><tr><td>Transaction date</td><td>Bill date, format: <code>yyyy/MM/dd</code></td><td>✅</td><td>2026/01/01</td></tr><tr><td>Transaction type</td><td>Expense or income</td><td>✅</td><td>支出 / 收入</td></tr><tr><td>Parent category</td><td>Level-1 category name</td><td>✅</td><td>伙食</td></tr><tr><td>Child category</td><td>Level-2 category name under the parent</td><td>✅</td><td>早餐</td></tr><tr><td>Inflow amount</td><td>Amount used when type is income</td><td>✅</td><td>100.00</td></tr><tr><td>Outflow amount</td><td>Amount used when type is expense</td><td>✅</td><td>15</td></tr><tr><td>Account</td><td>Account name (prefer an existing account)</td><td>✅</td><td>默认账户</td></tr><tr><td>Note</td><td>Bill note</td><td>❌</td><td>午餐</td></tr><tr><td>Tags</td><td>Tag names, separated by commas</td><td>❌</td><td>工作餐,聚餐</td></tr></tbody></table><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><ul><li><strong>Date</strong>: must be <code>YYYY/MM/DD</code> (e.g. <code>2026/01/01</code>)</li><li><strong>Amount</strong>: numeric, decimals supported (e.g. <code>100.00</code>)</li><li><strong>Type</strong>: must be <code>支出</code> (expense) or <code>收入</code> (income)</li><li><strong>Category &amp; account</strong>: if missing in Koala, Koala may create them during import</li></ul><hr><h2 id="📚-related-guides" tabindex="-1">📚 Related Guides <a class="header-anchor" href="#📚-related-guides" aria-label="Permalink to &quot;📚 Related Guides&quot;">​</a></h2><ul><li><a href="./02-wechat-bill-import-guide">WeChat Bill Import</a></li><li><a href="./03-alipay-bill-import-guide">Alipay Bill Import</a></li><li><a href="./04-multi-ledger-guide">Multi-ledger</a></li></ul><hr><p><strong>Last updated</strong>: Jan 2026</p>`,37)])])}const g=t(l,[["render",o]]);export{c as __pageData,g as default};
